def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return max(0.0, min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    prev_bids = []
    bob_bid = None
    cindy_bid = None
    urgent_opp = False

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if agent_id == 'Bob':
                bob_bid = float(bid)
            if agent_id == 'Cindy':
                cindy_bid = float(bid)
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    stable_ref = bob_bid if bob_bid is not None else highest_prev

    danger = hp <= 3 or no_water_days >= 1
    very_danger = hp <= 2 or no_water_days >= 2
    tight_supply = slots <= 1

    if very_danger:
        target = max(72.0, stable_ref + 6.0)
        if cindy_bid is not None and cindy_bid < 110:
            target = max(target, cindy_bid + 2.0)
        return max(0.0, min(budget, target))

    if tight_supply:
        if danger:
            target = max(66.0, stable_ref + 2.5)
            return max(0.0, min(budget, target))
        if stable_ref >= 60.0:
            return max(0.0, min(budget, 34.0))
        target = max(58.0, stable_ref + 1.5)
        return max(0.0, min(budget, target))

    if slots >= 2:
        if danger:
            target = max(52.0, stable_ref)
            return max(0.0, min(budget, target))
        if urgent_opp and highest_prev >= 80.0:
            return max(0.0, min(budget, 24.0))
        if stable_ref >= 60.0:
            return max(0.0, min(budget, 28.0))
        return max(0.0, min(budget, 41.0))

    return max(0.0, min(budget, 45.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Yesterday reaction: look at bids from alive opponents.
    prev_bids = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base urgency from our hp.
    if hp <= 2:
        urgency = 0.95
    elif hp <= 4:
        urgency = 0.75
    else:
        urgency = 0.55

    # Supply pressure: with only 15-25 supply, competition matters.
    # If supply is closer to minimum, increase bids to secure allocation.
    if supply <= 16.0:
        supply_factor = 1.10
    elif supply <= 19.0:
        supply_factor = 1.00
    else:
        supply_factor = 0.90

    target = DAILY_SALARY * urgency * supply_factor

    # If Cindy-style pressure existed yesterday (high highest bid), overbid slightly.
    # This exploits the observed willingness to pay while staying within budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Bid just above the strongest prior pressure.
        target = max(target, highest_prev_bid + 2.0)
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        target = max(target, highest_prev_bid * 0.85)

    # Never exceed budget.
    bid = min(budget, target)

    # If budget is very low, still try to get some water when hp is critical.
    if bid <= 0.0:
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.3)

    return float(max(0.0, bid))
